function sign(level){if(selectedVersion!=='v3'){toast('Only the latest v3 return can be signed.');return;}if(role()!==level){toast(`Only the ${level} role can sign this level.`);return;}if(blockers()){toast('Unresolved critical checks or blocking notes prevent sign-off.');return;}if(level==='partner'&&!state.signoffs.reviewer){toast('Independent reviewer must sign first.');return;}if(state.filing){toast('Filed workpaper is frozen.');return;}state.signoffs[level]={by:user().name,actor:activeStaff,at:new Date().toISOString(),version:selectedVersion,auditAt:state.audit.length};audit('signoff',level,`${level} sign-off with ${openIssues().length} advisory open issues`);toast('Signed and logged.');render();}
function modifyGuard(){if(state.filing){toast('Filed workpaper frozen: use amendment record rather than changing the original.');return false;}return true;}
function statusChange(id,reason,status){if(!modifyGuard())return;state.issueStatus[id]={status,reason,byName:user().name,actor:activeStaff,at:new Date().toISOString()};audit('exception_'+status,id,reason);invalidate('Exception assessment changed: '+id);save();openIssue(id);render();toast(`Exception ${status}.`);}
function formValues(id){const f=document.getElementById(id);return f?new FormData(f):null}
function handleClick(e){const b=e.target.closest('[data-route-go],[data-route],[data-act],#exportTop,#exportReview,#estimateAdj,#saveChoice,#nextPage,#prevPage');if(!b)return;
 if(b.dataset.routeGo){ui.filter='all';ui.query='';ui.page=0;viewPage(b.dataset.routeGo);return;}
 if(b.dataset.route){ui.filter='all';ui.query='';ui.page=0;viewPage(b.dataset.route);return;}
 if(b.id==='exportTop'||b.id==='exportReview'){doExport();return;}
 if(b.id==='estimateAdj'){estimate();return;}
 if(b.id==='nextPage'||b.id==='prevPage'){ui.page+=b.id==='nextPage'?1:-1;render();return;}
 if(b.id==='saveChoice'){if(!modifyGuard())return;const s=data.what_if.alternatives.find(c=>c.id===ui.selectedWhatIf);const rationale=prompt('What tax judgment and authority justify considering this alternative?');if(!rationale?.trim())return;state.decisions.push({id:'d-'+Date.now(),label:s.description,type:'engine_precomputed_scenario',scenario:s.id,fed:s.federal.total_tax_change,ca:s.california.total_tax_change,rationale:rationale.trim(),actorName:user().name,at:new Date().toISOString()});audit('judgment',s.id,rationale);invalidate('New judgment recorded');render();return;}
 const id=b.dataset.id,act=b.dataset.act;
 if(act==='close'){closeDrawer();return;}
 if(act==='download-attachment'){const a=state.attachments.find(x=>x.id===id);if(!a||!a.data?.startsWith('data:'))return;const x=document.createElement('a');x.href=a.data;x.download=a.name;x.click();audit('attachment_accessed',a.docId,a.name);return;}
 if(act==='area-tab'){ui.areaTab=b.dataset.tab;render();return;}
 if(act==='issue'){openIssue(id);return;}
 if(act==='line'){openLine(b.dataset.key);return;}
 if(act==='doc'){openDoc(id);return;}
 if(act==='source'){const ev=evById[id];if(ev)openDoc(ev.document_id,id,b.dataset.back||null);return;}
 if(act==='ref'){openRef(b.dataset.ref);return;}
 if(act==='reopen-issue'){statusChange(id,'Reopened for additional independent review','open');return;}
 if(act==='sign'){sign(b.dataset.level);return;}
 if(act==='file'){if(selectedVersion!=='v3'){toast('Select current v3 before freezing.');return;}if(role()!=='partner'||blockers()||!state.signoffs.partner||!state.signoffs.reviewer){toast('Filing gate denied.');return;}if(confirm('Freeze the current review record? This is NOT actual electronic filing.')){state.filing={at:new Date().toISOString(),by:user().name,version:selectedVersion};audit('filing_freeze','engagement','Demonstration freeze, no live e-file');render();}return;}
 if(act==='close-note'){if(!modifyGuard())return;const item=state.notes.find(n=>n.id===id);if(!item)return;const why=prompt('How was this resolved? Cite evidence or the person who confirmed it.');if(!why?.trim())return;item.status='closed';item.resolution=why.trim();item.closedBy=user().name;item.closedAt=new Date().toISOString();audit('review_note_closed',id,why);invalidate('Review note closed');render();return;}
 if(act==='answer-question'){if(!modifyGuard())return;const q=state.questions.find(x=>x.id===id);const answer=prompt('Record the client or colleague response (include source/received date):');if(!answer?.trim())return;q.answer=answer.trim();q.answeredBy=user().name;q.answeredAt=new Date().toISOString();audit('client_answer',id,answer);invalidate('New client answer');render();return;}
 if(act==='replay'){const at=b.dataset.when,latest=data.return_versions.filter(x=>x.computed_at<=at).slice(-1)[0]||data.return_versions[0];selectedVersion=latest.version;$('#versionSelect').value=selectedVersion;viewPage('overview');toast(`Replaying event as of ${date(at)}. Snapshot: ${latest.version}.`);return;}
}
function handleSubmit(e){const f=e.target;if(!['issueResolve','verifyLine','verifyDoc','noteForm','questionForm','adjustForm','attachForm'].includes(f.id))return;e.preventDefault();if(!modifyGuard())return;
 if(f.id==='attachForm'){const file=$('#attachInput')?.files?.[0],docId=f.dataset.id;if(!file)return;if(file.size>700*1024){toast('File too large for browser storage; use a smaller file for this demo.');return;}const reader=new FileReader();reader.onload=()=>{state.attachments.push({id:'att-'+Date.now(),docId,name:file.name,size:file.size,mime:file.type,data:String(reader.result),actor:activeStaff,byName:user().name,at:new Date().toISOString()});audit('file_attached',docId,file.name);invalidate('Supporting file attached');save();openDoc(docId);toast('Supporting file attached; server sync may take a moment.');};reader.readAsDataURL(file);return;}
 if(f.id==='issueResolve'){const reason=$('#issueReason').value.trim();if(reason.length<12){toast('Please provide a meaningful, evidence-backed resolution.');return;}statusChange(f.dataset.id,reason,'resolved');return;}
 if(f.id==='verifyLine'){const key=f.dataset.key,method=$('#verifyMethod').value,note=$('#verifyNote').value.trim();if(note.length<8){toast('Explain what you verified.');return;}state.verifications[`${selectedVersion}:${key}`]={byName:user().name,actor:activeStaff,at:new Date().toISOString(),method,note};audit('line_verified',key,note,{method});invalidate('Line evidence changed: '+key);openLine(key);toast('Verification saved.');return;}
 if(f.id==='verifyDoc'){const did=f.dataset.id,note=$('#docNote').value.trim();if(note.length<8){toast('Explain what you checked.');return;}state.documentChecks[did]={status:'verified',at:new Date().toISOString(),byName:user().name,actor:activeStaff,note};audit('document_verified',did,note);invalidate('Source evidence changed: '+did);openDoc(did);toast('Document verification saved.');return;}
 if(f.id==='noteForm'){const target=$('#noteTarget').value.trim(),text=$('#noteText').value.trim(),due=$('#noteDue').value,blocking=$('#noteBlocking').checked;state.notes.push({id:'n-'+Date.now(),target,text,due,blocking,status:'open',author:user().name,actor:activeStaff,at:new Date().toISOString()});audit('review_note',target,text);invalidate('New review note');render();toast('Review note created.');return;}
 if(f.id==='questionForm'){const txt=$('#questionText').value.trim(),to=$('#questionTo').value;state.questions.push({id:'q-'+Date.now(),text:txt,to,actor:activeStaff,actorName:user().name,at:new Date().toISOString()});audit('question_recorded',to,txt);invalidate('New client question');render();toast('Question recorded as evidence, not sent.');return;}
 if(f.id==='adjustForm'){const p=estimate(),why=$('#adjWhy').value.trim();if(!p||why.length<12){toast('Explain the proposed adjustment and its evidence.');return;}state.decisions.push({id:'d-'+Date.now(),label:`Proposed ${p.category} adjustment ${usd(p.delta)}`,type:'marginal_estimate_only',fed:p.fed,ca:p.ca,delta:p.delta,rationale:why,actorName:user().name,at:new Date().toISOString(),version:selectedVersion});audit('adjustment_proposed',p.category,why,{delta:p.delta,federalEstimate:p.fed,californiaEstimate:p.ca});invalidate('Proposed adjustment recorded');render();toast('Proposal recorded. Original engine output unchanged.');}
}
function handleChange(e){const t=e.target;
 if(t.id==='versionSelect'){selectedVersion=t.value;ui.page=0;ui.filter='all';render();toast('Viewing immutable '+selectedVersion+' snapshot.');return;}
 if(t.id==='staffSelect'){if(window.proofServer){window.changeActingStaff(t.value);return;}activeStaff=t.value;$('#avatar').textContent=user().name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();render();toast('Acting as '+user().name+' ('+role()+').');return;}
 if(t.id==='exceptionFilter'||t.id==='formFilter'){ui.filter=t.value;ui.page=0;render();return;}
 if(t.id==='docFilter'){ui.docFilter=t.value;render();return;}
 if(t.id==='scenarioSelect'){ui.selectedWhatIf=t.value;render();return;}
 if(t.id==='docPage'){refreshDocPage(t.dataset.doc,t.value,t.dataset.evid);return;}
 if(t.id==='importReview'){const file=t.files?.[0];if(!file)return;file.text().then(s=>{let rec=JSON.parse(s);if(rec.packet_client!==data.packet.client_id||!rec.review_state)throw Error('Not a compatible review export.');if(!confirm('Replace the existing browser review state with the imported file?'))return;state={...blankState(),...rec.review_state};save();render();toast('Review record imported.');}).catch(err=>toast('Import failed: '+err.message));}
}
let debounce;function handleInput(e){const t=e.target;if(t.id==='lineSearch'){const cur=t.selectionStart;ui.query=t.value;ui.page=0;clearTimeout(debounce);debounce=setTimeout(()=>{render();const x=$('#lineSearch');if(x){x.focus();x.setSelectionRange(Math.min(cur,x.value.length),Math.min(cur,x.value.length));}},180)}if(t.id==='docSearch'){const cur=t.selectionStart;ui.docQuery=t.value;clearTimeout(debounce);debounce=setTimeout(()=>{render();const x=$('#docSearch');if(x){x.focus();x.setSelectionRange(Math.min(cur,x.value.length),Math.min(cur,x.value.length));}},180)}}
async function bootstrap(){try{if(window.ensureDemoSession)await window.ensureDemoSession();const response=await fetch(window.proofServer?'/api/packet':'packet.json');if(!response.ok)throw Error(`HTTP ${response.status}`);data=await response.json();docById=Object.fromEntries(data.documents.map(d=>[d.id,d]));evById=Object.fromEntries(data.extracted_values.map(e=>[e.id,e]));initState();if(window.loadSharedState)await window.loadSharedState();issues=deriveIssues();if(window.proofUser)activeStaff=window.proofUser.id;$('#staffSelect').innerHTML=data.firm.staff.map(s=>`<option value="${s.id}">${esc(s.name)} · ${readable(s.role)}</option>`).join('');activeStaff=window.proofUser?.id||data.firm.staff[0].id;$('#staffSelect').value=activeStaff;$('#avatar').textContent=user().name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();document.addEventListener('click',e=>handleClick(e));document.addEventListener('submit',e=>handleSubmit(e));document.addEventListener('change',e=>handleChange(e));document.addEventListener('input',e=>handleInput(e));$('#drawerBackdrop').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});viewPage('overview');}catch(e){console.error(e);$('#content').innerHTML=hero('LOAD ERROR','Could not load the JSON packet',`Run this directory through a local web server: python3 -m http.server 8080. Details: ${e.message}`)}}
bootstrap();
// The area records page is an alternative, non-spreadsheet entry point for
// experienced CPAs: each collection is generated from the supplied packet.
function areaView(){const tab=ui.areaTab,items=[['summary','Return vs last year'],['assets','Assets & depreciation'],['sales','Sales lots'],['basis','Basis & carryovers'],['business','Books to tax'],['states','California split']];
 let html=hero('SPECIALIST WORKPAPERS','Area records','A guided view of the accountant’s expected records; always connected to the same return lines and primary evidence, with no parallel source of truth.');
 html+=`<div class="toolbar">${items.map(([id,name])=>`<button class="btn ${tab===id?'primary':'ghost'}" data-act="area-tab" data-tab="${id}">${esc(name)}</button>`).join('')}</div>`;
 if(tab==='summary'){
 const py=data.prior_years.return_2024.lines, keys=['F1040.1a','F1040.2b','F1040.3b','F1040.7','F1040.8','F1040.9','F1040.11','F1040.12','F1040.13','F1040.15','F1040.16','F1040.24','F1040.33'];
 html+=panel('Federal return compared with 2024',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Return line</th><th>Caption</th><th class="right">2024 filed</th><th class="right">2025 engine</th><th class="right">Change</th></tr></thead><tbody>${keys.map(k=>{const now=line(k)?.value,old=py[k],diff=typeof now==='number'&&typeof old==='number'?now-old:null;return `<tr class="data-row" data-act="line" data-key="${k}"><td><strong>${k}</strong></td><td>${esc(line(k)?.label||data.prior_years.return_2024.line_labels?.[k]||'—')}</td><td class="right money">${usd(old)}</td><td class="right money">${usd(now)}</td><td class="right money">${diff!==null?(diff>0?'+':'')+usd(diff):'—'}</td></tr>`}).join('')}</tbody></table></div>`, 'A variance exceeding 10% and $1,000 requires judgment per firm standards');
 html+=panel('Jurisdiction-level overview',`<div class="two-col panel-body">${['federal','california'].map(k=>`<div class="callout"><div class="section-label">${k}</div>${Object.entries(v().summary[k]).map(([field,val])=>`<div class="bar-item"><span>${readable(field)}</span><strong>${usd(val)}</strong></div>`).join('')}</div>`).join('')}</div>`);
 }
 if(tab==='assets'){
 const assets=v().assets;html+=panel(`Asset register · ${assets.length} assets`,`<div class="table-scroll"><table class="data-table"><thead><tr><th>Asset</th><th>Method / life</th><th class="right">Cost</th><th class="right">2025 federal</th><th class="right">2025 CA</th><th>Disposition</th></tr></thead><tbody>${assets.map(a=>`<tr><td><strong>${esc(a.asset_id)}</strong><div class="small-label">${esc(a.description)}</div></td><td>${esc(a.method)} · ${esc(a.life_years)} yrs</td><td class="right money">${usd(a.cost)}</td><td class="right money">${usd(a.federal.depreciation_2025)}</td><td class="right money">${usd(a.california.depreciation_2025)}</td><td>${esc(a.disposed?.date||'Held')}</td></tr>`).join('')}</tbody></table></div>`,'A consistent row for each federal, California and AMT treatment');
 html+=`<div class="notice">The register is read directly from return_versions[].assets. Federal / California differences, dispositions and accumulated depreciation remain visible. For supporting invoices, open D22, D47 and D51 in the Evidence library.</div>`;
 }
 if(tab==='sales'){
 const lots=v().lines.filter(l=>l.form==='F8949'), q=ui.query.toLowerCase(),subset=lots.filter(l=>(l.key+' '+l.label).toLowerCase().includes(q)),from=ui.page*60;
 html+=`<div class="toolbar"><input id="lineSearch" class="search" placeholder="Search brokerage lots by name or lot ID" value="${esc(ui.query)}"><span class="muted tiny">${subset.length} matching lots · ${lots.length} total</span></div>`+panel('Capital transactions',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Lot key</th><th>Sale and provenance</th><th class="right">Reported gain/loss</th></tr></thead><tbody>${subset.slice(from,from+60).map(l=>`<tr class="data-row" data-act="line" data-key="${esc(l.key)}"><td><strong>${esc(l.key)}</strong></td><td>${esc(l.label)}</td><td class="right money">${usd(l.value)}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><button class="btn ghost" id="prevPage" ${ui.page===0?'disabled':''}>← Previous</button> <button class="btn ghost" id="nextPage" ${(ui.page+1)*60>=subset.length?'disabled':''}>Next →</button></div>`,'Rows are paginated instead of forcing the reviewer through hundreds of sales');
 }
 if(tab==='basis'){
 const basis=data.prior_years.basis_records,carry=data.prior_years.carryovers_into_2025;
 html+=panel('Basis tracked across years',`<div class="panel-body">${Object.entries(basis).map(([k,rows])=>`<h3>${readable(k)}</h3><div class="table-scroll"><table class="data-table"><thead><tr>${Object.keys(rows[0]||{}).map(x=>`<th>${readable(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${Object.values(row).map(val=>`<td>${val===null?severity('warning'):esc(val)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')}</div>`,'Missing year basis is explicitly identified rather than silently imputed');
 html+=panel('Carryovers received for 2025',`<div class="panel-body">${Object.entries(carry).map(([k,val])=>`<div class="bar-item"><span>${readable(k)}</span><strong>${typeof val==='number'?usd(val):esc(typeof val==='object'?JSON.stringify(val):val)}</strong></div>`).join('')}</div>`);
 }
 if(tab==='business'){
 const D14=docById.D14;const rows=['SchC.1','SchC.7','SchC.28','SchC.29','SchC.30','SchC.31'];
 html+=panel('Lindqvist Studio · books → taxable income',`<div class="panel-body"><div class="two-col"><div class="callout"><small class="section-label">Books · cash basis</small><div class="outcome">$151,300</div><p class="tiny">Document D14: gross book revenue</p><button class="link" data-act="doc" data-id="D14">Inspect profit and loss →</button></div><div class="callout amber"><small class="section-label">Engine Schedule C gross receipts</small><div class="outcome">${usd(line('SchC.1')?.value)}</div><p class="tiny">Includes apparently duplicated Paywell proceeds</p><button class="link" data-act="issue" data-id="SCHC-1099K-DUP">Investigate mismatch →</button></div></div><h3>Tax adjustments and output</h3>${rows.map(k=>{const l=line(k);return l?`<div class="bar-item"><button class="link" data-act="line" data-key="${k}">${esc(k)} · ${esc(l.label)}</button><strong>${usd(l.value)}</strong></div>`:''}).join('')}<div class="notice warn">The original engine output is unchanged. Reviewer-signed changes need a real recomputation in production; the packet supplies only marginal rates for illustrative estimates.</div></div>`, 'Bridge books figures to Schedule C, without fabricating corrected tax results');
 }
 if(tab==='states'){
 const l=v().lines.filter(l=>l.form==='SchCA540NR').slice(0,90);
 html+=panel('California sourcing and residency',`<div class="panel-body"><div class="two-col"><div class="callout"><strong>California</strong><p>January 1 – July 14, 2025</p></div><div class="callout"><strong>Texas</strong><p>July 15 – December 31, 2025</p></div></div><div class="notice warn">A July 18 paystub documents the work location change while W-2 payroll coding continued to California. Review source allocation, not the engine’s state field alone. <button class="link" data-act="issue" data-id="CA-RESIDENCY">Review exception →</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Form / line</th><th>Description</th><th class="right">Value</th></tr></thead><tbody>${l.map(x=>`<tr class="data-row" data-act="line" data-key="${esc(x.key)}"><td>${esc(x.key)}</td><td>${esc(x.label)}</td><td class="right money">${usd(x.value)}</td></tr>`).join('')}</tbody></table></div>`,'California Schedule CA (540NR) columns and inputs');
 }
 return html;
}
